import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:crypto/crypto.dart' as digest;
import 'package:cryptography/cryptography.dart';

/// Cryptographic proof generated by a Verifiable Random Function (VRF).
///
/// Contains the deterministic pseudorandom [outputHash] (used as the blinded
/// leaf index in the Key Transparency tree) and the verifiable [proofBytes].
final class VrfProof {
  final Uint8List outputHash;
  final Uint8List proofBytes;

  const VrfProof({required this.outputHash, required this.proofBytes});

  Map<String, dynamic> toJson() => {
    'outputHash': base64Encode(outputHash),
    'proof': base64Encode(proofBytes),
  };

  factory VrfProof.fromJson(Map<String, dynamic> json) => VrfProof(
    outputHash: Uint8List.fromList(base64Decode(json['outputHash'] as String)),
    proofBytes: Uint8List.fromList(base64Decode(json['proof'] as String)),
  );
}

/// Key pair for evaluating and publishing VRF proofs.
final class VrfKeyPair {
  final Uint8List secretKey;
  final Uint8List publicKey;

  const VrfKeyPair({required this.secretKey, required this.publicKey});

  /// Generate a secure 32-byte VRF key pair.
  static Future<VrfKeyPair> generate() async {
    final random = Random.secure();
    final seed = Uint8List.fromList(
      List<int>.generate(32, (_) => random.nextInt(256)),
    );
    final keyPair = await Ed25519().newKeyPairFromSeed(seed);
    final pubKey = await keyPair.extractPublicKey();
    return VrfKeyPair(
      secretKey: seed,
      publicKey: Uint8List.fromList(pubKey.bytes),
    );
  }
}

/// Verifiable Random Function (VRF) engine for blinded search in Key Transparency.
///
/// Prevents directory crawling and user enumeration: instead of storing `accountId`
/// or username directly in public Merkle trees, leaves are indexed by the 32-byte
/// deterministic VRF output hash. Only a client querying a specific known `accountId`
/// can verify the server's proof and check the Merkle inclusion path.
abstract final class NiosVrf {
  static const String _hashDomain = 'nios-vrf-hash-v1:';
  static const String _proofDomain = 'nios-vrf-proof-v1:';

  /// Evaluates the VRF for [input] using [keyPair].
  ///
  /// Returns the deterministic [outputHash] and zero-knowledge [proofBytes].
  static Future<VrfProof> evaluate({
    required VrfKeyPair keyPair,
    required String input,
  }) async {
    final inputBytes = utf8.encode(input);

    // 1. Compute deterministic pseudorandom output hash
    final hmacKey = digest.Hmac(digest.sha512, keyPair.secretKey);
    final hashDigest = hmacKey.convert([
      ...utf8.encode(_hashDomain),
      ...inputBytes,
    ]);
    final outputHash = Uint8List.fromList(hashDigest.bytes.sublist(0, 32));

    // 2. Generate verifiable signature proof over (input || outputHash) using Ed25519
    final ed25519 = Ed25519();
    final signer = await ed25519.newKeyPairFromSeed(keyPair.secretKey);
    final commitmentData = Uint8List.fromList([
      ...utf8.encode(_proofDomain),
      ...inputBytes,
      ...outputHash,
    ]);
    final signature = await ed25519.sign(commitmentData, keyPair: signer);

    return VrfProof(
      outputHash: outputHash,
      proofBytes: Uint8List.fromList(signature.bytes),
    );
  }

  /// Verifies that [proof] was honestly generated for [input] under [publicKey].
  static Future<bool> verify({
    required Uint8List publicKey,
    required String input,
    required VrfProof proof,
  }) async {
    if (publicKey.length != 32 ||
        proof.outputHash.length != 32 ||
        proof.proofBytes.length != 64) {
      return false;
    }

    final inputBytes = utf8.encode(input);
    final commitmentData = Uint8List.fromList([
      ...utf8.encode(_proofDomain),
      ...inputBytes,
      ...proof.outputHash,
    ]);

    final ed25519 = Ed25519();
    final pubKey = SimplePublicKey(publicKey, type: KeyPairType.ed25519);
    final sig = Signature(proof.proofBytes, publicKey: pubKey);

    try {
      return await ed25519.verify(commitmentData, signature: sig);
    } catch (_) {
      return false;
    }
  }
}
